return {["fb35_01"]={["down"]=[[fb35_02]],["dsc"]=[[这是虚渺童姥闭关修练的地方，只见一个身材娇小，貌如处子的十八九岁的女子盘膝而坐，她就是闻名天下的虚渺童姥。如果不是她的亲传弟子，千万不要轻易打搅。]],["id"]=[[fb35_01]],["item1"]=[[lylitem1]],["name"]=[[闭关室]],["permission"]=1,["role1"]=[[fb35r01_1]],["role2"]=[[fb35r01_2]],["stepMusic"]=[[jiaobu]]},["fb35_02"]={["down"]=[[fb35_03]],["dsc"]=[[这是闭关室南边，北面有一扇大门。]],["id"]=[[fb35_02]],["name"]=[[闭关室大门]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb35_01]]},["fb35_03"]={["down"]=[[fb35_10]],["dsc"]=[[一条小道蜿延曲折地通向远方，两旁是郁郁葱葱的树林，微风吹过，树叶发出奚索的声音。]],["id"]=[[fb35_03]],["name"]=[[小道]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb35_02]]},["fb35_04"]={["down"]=[[fb35_13]],["dsc"]=[[这是『虚渺宫』的裁缝室。几个女子围坐在一块，飞针走线，苦练女红，难道她们是为了以后找一个好婆家吗？]],["id"]=[[fb35_04]],["item1"]=[[fb33item8]],["item2"]=[[fb33item8]],["item3"]=[[fb33item17]],["name"]=[[潇湘馆]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb35_05"]={["dsc"]=[[这是『虚渺宫』关押犯人的地方，屋中光线昏暗，气味难闻。屋角隐隐约约有个人影。]],["id"]=[[fb35_05]],["item1"]=[[fb33item11]],["item2"]=[[ycitem1]],["name"]=[[囚室]],["permission"]=1,["right"]=[[fb35_06]],["role1"]=[[fb35r05_1]],["stepMusic"]=[[jiaobu]]},["fb35_06"]={["dsc"]=[[这是一条非常精美的长廊，柱子和栏杆是用华贵的紫檀木制成，上面雕饰着美丽的图画，画工精巧，美不胜收。地板不知是用什么材料做的，走在上面毫无声息，你只感到脚下软软的，非常舒服。西面是虚渺童姥关押犯人的地方，那里是本派禁地，没有童姥的许可，谁也不能进去。]],["id"]=[[fb35_06]],["left"]=[[fb35_05]],["name"]=[[画廊]],["permission"]=1,["right"]=[[fb35_07]],["role1"]=[[fb35r06_1]],["role2"]=[[fb35r06_2]],["role3"]=[[fb35r06_3]],["stepMusic"]=[[jiaobu]]},["fb35_07"]={["down"]=[[fb35_17]],["dsc"]=[[这是一条非常精美的长廊，柱子和栏杆是用华贵的紫檀木制成，上面雕饰着美丽的图画，画工精巧，美不胜收。地板不知是用什么材料做的，走在上面毫无声息，你只感到脚下软软的，非常舒服。]],["id"]=[[fb35_07]],["left"]=[[fb35_06]],["name"]=[[画廊]],["permission"]=1,["right"]=[[fb35_08]],["stepMusic"]=[[jiaobu]]},["fb35_08"]={["dsc"]=[[这是一条非常精美的长廊，柱子和栏杆是用华贵的紫檀木制成，上面雕饰着美丽的图画，画工精巧，美不胜收。地板不知是用什么材料做的，走在上面毫无声息，你只感到脚下软软的，非常舒服。走廊东面通往书房。]],["id"]=[[fb35_08]],["left"]=[[fb35_07]],["name"]=[[画廊]],["permission"]=1,["right"]=[[fb35_09]],["role1"]=[[fb35r08_1]],["role2"]=[[fb35r08_2]],["stepMusic"]=[[jiaobu]]},["fb3