"fb35_19"]={["dsc"]=[[你的眼前出现了一个美丽的花园，花园里种着一些花，花从中隐约可见飘渺的倩影，那是宫中的姐妹们在玩耍。花园中央有一座假山。花园的东西两头是长廊，北边有一条小道通向虚渺童姥修练之处。]],["id"]=[[fb35_19]],["item1"]=[[fb33item9]],["item2"]=[[fb33item9]],["left"]=[[fb35_18]],["name"]=[[花园]],["permission"]=1,["right"]=[[fb35_20]],["stepMusic"]=[[jiaobu]],["up"]=[[fb35_10]]},["fb35_20"]={["dsc"]=[[这是一条非常精美的长廊，柱子和栏杆是用华贵的紫檀木制成，上面雕饰着美丽的图画，画工精巧，美不胜收。地板不知是用什么材料做的，走在上面毫无声息，你只感到脚下软软的，非常舒服。一阵阵花香从西边传来。]],["id"]=[[fb35_20]],["item1"]=[[fb33item8]],["item2"]=[[fb33item9]],["item3"]=[[fb33item9]],["left"]=[[fb35_19]],["name"]=[[画廊]],["permission"]=1,["right"]=[[fb35_21]],["stepMusic"]=[[jiaobu]],["up"]=[[fb35_12]]},["fb35_21"]={["down"]=[[fb35_28]],["dsc"]=[[这是一条非常精美的长廊，柱子和栏杆是用华贵的紫檀木制成，上面雕饰着美丽的图画，画工精巧，美不胜收。地板不知是用什么材料做的，走在上面毫无声息，你只感到脚下软软的，非常舒服。走廊东面是憩凤阁，是虚渺宫弟子休息的地方。]],["id"]=[[fb35_21]],["item1"]=[[fb33item6]],["left"]=[[fb35_20]],["name"]=[[画廊]],["permission"]=1,["right"]=[[fb35_22]],["stepMusic"]=[[jiaobu]]},["fb35_22"]={["dsc"]=[[这里是虚渺宫弟子睡觉的地方，一进门就闻到一阵悠悠的香气，只见房中点了一支大红烛，照的满室生春，床上珠罗纱的帐子，白色缎被上绣着一只黄色的凤凰，壁上挂着一幅工笔仕女图。西首一张几上供着一盆兰花，架子上停着一只白鹦鹉。]],["id"]=[[fb35_22]],["item1"]=[[fb33item22]],["left"]=[[fb35_21]],["name"]=[[憩凤阁]],["permission"]=2,["role1"]=[[fb35r22_1]],["stepMusic"]=[[jiaobu]]},["fb35_23"]={["dsc"]=[[这是间厨房，浓郁的饭菜香味一个劲地钻进你的鼻子，你仿佛听到“咕咕”的响声，环顾四周不知来源。原来是你的肚子作怪。]],["id"]=[[fb35_23]],["name"]=[[藕香榭]],["permission"]=2,["right"]=[[fb35_24]],["role1"]=[[fb35r23_1]],["stepMusic"]=[[jiaobu]]},["fb35_24"]={["dsc"]=[[这是一条非常精美的长廊，柱子和栏杆是用华贵的紫檀木制成，上面雕饰着美丽的图画，画工精巧，美不胜收。地板不知是用什么材料做的，走在上面毫无声息，你只感到脚下软软的，非常舒服。]],["id"]=[[fb35_24]],["left"]=[[fb35_23]],["name"]=[[画廊]],["permission"]=2,["right"]=[[fb35_25]],["role1"]=[[fb35r24_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb35_17]]},["fb35_25"]={["dsc"]=[[这是一条非常精美的长廊，柱子和栏杆是用华贵的紫檀木制成，上面雕饰着美丽的图画，画工精巧，美不胜收。地板不知是用什么材料做的，走在上面毫无声息，你只感到脚下软软的，非常舒服。]],["id"]=[[fb35_25]],["left"]=[[fb35_24]],["name"]=[[画廊]],["permission"]=2,["right"]=[[fb35_26]],["role1"]=[[fb35r25_1]],["stepMusic"]=[[jiaobu]]},["fb35_26"]={["down"]=[[fb35_30]],["dsc"]=[[这是一条非常精美的长廊，柱子和栏杆是用华贵的紫檀木制成，上面雕饰着美丽的图画，画工精巧，美不胜收。地板不知是用什么材料做的，走在上面毫无声息，你只感到脚下软软的，非常舒服。一阵阵花香从北边传来。]],["id"]=[[fb35_26]],["item1"]=[[fb33item5]],["left"]=[[fb35_25]],["name"]=[[画廊]],["permission"]=1,["right"]=[[fb35_27]],["stepMusic"]=[[jiaobu]]},["fb35_27"]={["dsc"]=[[这是一条非常精美的长廊，柱子和栏杆是用华贵的紫檀木制成，上面雕饰着美丽的图画，画工精巧，美不胜收。地板不知是用什么材料做的，走在上面毫无声息，你只感到脚下软软的，非常舒服。]],["id"]=[[fb35_27]],["item1"]=[[fb33item8]],["item2"]=[[fb33item8]],["item3"]=[[fb33item9]],["left"]=[[fb35_26]],["name"]=[[画廊]],["permission"]=1,["right"]=[[fb35_28]],["stepMusic"]=[[jiaobu]]},["fb35_28"]={["dsc"]=[[这是一条非常精美的长廊，柱子和栏杆是用华贵的紫檀木制成，上面雕饰着美丽的图画，画工精巧，美不胜收。地板不知是用什么材料做的，走在上面毫无声息，你只感到脚下软软的，非常舒服。走廊东面是一间房间，里面不时传出几声女子的娇叱。]],["id"]=[[fb35_28]],["item1"]=[[fb33item8]],["item2"]=[[fb33item9]],["left"]=[[fb35_27]],["name"]=[[画廊]],["permission"]=1,["right"]=[[fb35_29]],["stepMusic"]=[[jiaobu]],["up"]=[[fb35_21]]},["fb35_29"]={["dsc"]=[[这里是虚渺宫弟子练功的地方。有几个妙龄女子正在专心致致地练武，有几个手持竹剑，在互相拆招，身法灵动，犹如穿花蝴蝶一般，你不禁看花了眼，别的人则坐在地上的蒲团上苦练内力。]],["id"]=[[fb35_29]],["left"]=[[fb35_28]],["name"]=[[戏凤阁]],["permission"]=2,["role1"]=[[fb35r29_1]],["role2"]=[[fb35r29_2]],["role3"]=[[jinianwanjia]],["stepMusic"]=[[jiaobu]]},["fb35_30"]={["down"]=[[fb35_31]],["dsc"]=[[这就是『虚渺宫』独尊厅。大厅全是以巨石砌成，石块之间竟无半点缝隙，令人称奇。厅内矗立着四根石柱，皆为坚硬的花岗石所制。]],["id"]=[[fb35_30]],["name"]=[[独尊厅]],["permission"]=1,["role1"]=[[fb35r30_1]],["role2"]=[[fb35r30_2]],["role3"]=[[fb35r30_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb35_26]]},["fb35_31"]={["down"]=[[fb35_32]],["dsc"]=[[这就是通向『虚渺宫』独尊厅的大门。大门左右各有一头石雕的猛鹫，高达三丈有余，尖喙巨爪，神骏非凡，栩栩如生，似乎随时要腾空而去。]],["id"]=[[fb35_31]],["name"]=[[独尊厅大门]],["permission"]=1,["role1"]=[[fb35r31_1]],["role2"]=[[fb35r31_2]],["role3"]=[[fb35r31_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb35_30]]},["fb35_32"]={["down"]=[[fb35_34]],["dsc"]=[[这是一条青石铺成的宽敞大道，每块青石都是长约八尺，宽约三尺，甚是整齐，堪称巧夺天工。道旁是郁郁葱葱的松树林，不时可以看到一两只松鼠蹦蹦跳跳地跃向树林深处。往北望去，一座巨大的石堡巍然耸立。]],["id"]=[[fb35_32]],["item1"]=[[fb33item4]],["name"]=[[青石大道]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb35_31]]},["fb35_33"]={["down"]=[[fb35_35]],["dsc"]=[[这里就快到缥缈峰绝顶了，越往上走，山势越高，缭绕在你身边的白雾愈来愈浓，往南则是下山的路。沿着山道没走几步，在你眼前出现一个石坊，上书『仙愁门』三个大字，盖因上山之艰辛吧。]],["id"]=[[fb35_33]],["name"]=[[仙愁门]],["permission"]=1,["right"]=[[fb35_34]],["role1"]=[[fb35r33_1]],["role2"]=[[fb35r33_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb35_112]]},["fb35_34"]={["dsc"]=[[这是一条青石铺成的宽敞大道，每块青石都是长约八尺，宽约三尺，甚是整齐，堪称巧夺天工。道旁是郁郁葱葱的松树林，不时可以看到一两只松鼠蹦蹦跳跳地跃向树林深处。往北望去，一座巨大的石堡巍然耸立。]],["id"]=[[fb35_34]],["item1"]=[[fb33item3]],["left"]=[[fb35_33]],["name"]=[[青石大道]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb35_32]]},["fb35_35"]={["down"]=[[fb35_36]],["dsc"]=[[山道到此突然消失，在你面前是一条山涧，山涧之中云雾缭绕，你根本无法看清对面。一条铁索深入云中，旁边有一块石碑。]],["id"]=[[fb35_35]],["name"]=[[百丈涧]],["permission"]=1,["role1"]=[[2019qxcdg1a]],["role2"]=[[2019qxcdg1b]],["stepMusic"]=[[jiaobu]],["up"]=[[fb35_33]]},["fb35_36"]={["dsc"]=[[这是通向『虚渺宫』的必经之路，山道被一块如鹰喙突出的巨岩截断，巨岩光可鉴人，只有中间凿出了一条窄窄的石阶通向山道的那一头。你小心翼翼地试着踏了上去，心想:我能过去吧。]],["id"]=[[fb35_36]],["name"]=[[失足岩]],["permission"]=1,["right"]=[[fb35_37]],["stepMusic"]=[[jiaobu]],["up"]=[[fb35_35]]},["fb35_37"]={["dsc"]=[=[这是通向[虚渺宫]的必经之路，一条小道蜿蜒曲折地通向缥缈峰顶。路的右侧是一条陡峭的山崖，一阵山风吹过，你似乎听见从下面传来几声惨号，你心中一凛，不禁加快脚步赶紧离开这里。]=],["id"]=[[fb35_37]],["item1"]=[[fb33item2]],["item2"]=[[fb33item14]],["left"]=[[fb35_36]],["name"]=[[断魂崖]],["permission"]=1,["right"]=[[fb35_38]],["role1"]=[[fb35r37_1]],["stepMusic"]=[[jiaobu]]},["fb35_38"]={["dsc"]=[[这里是缥缈峰山脚，抬头上望，缥缈峰耸入云天，峰顶白云缭绕，宛若仙境。白云深处隐约可见琼楼玉宇，那就是令江湖人物闻名丧胆的『虚渺宫』。听说宫中住着一些武艺高强的女侠，而且只收女弟子为徒。]],["id"]=[[fb35_38]],["item1"]=[[fb33item15]],["left"]=[[fb35_37]],["name"]=[[缥缈峰山脚]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb35_39"]={["dsc"]=[[你的眼前是一条用汉白玉铺成的台阶，一直向下延伸，两边的墙壁都是花岗岩，墙上隔十来步就有一盏油灯，使你能看清周围。]],["id"]=[[fb35_39]],["item1"]=[[fb33item53]],["item2"]=[[fb33item55]],["name"]=[[密道]],["permission"]=1,["right"]=[[fb35_40]],["roomBgm"]=[[jinzhang_incave]],["roomBgmRule"]=1,["stepMusic"]=[[jiaobu]]},["fb35_40"]={["dsc"]=[[你的眼前是一条用汉白玉铺成的台阶，一直向下延伸，两边的墙壁都是花岗岩，墙上隔十来步就有一盏油灯，使你能看清周围。]],["id"]=[[fb35_40]],["left"]=[[fb35_39]],["name"]=[[密道]